import { DomainValidationError } from "./errors";

export class User {
  private constructor(
    readonly id: string,
    readonly name: string,
  ) {}

  static create(id: string, name: string): User {
    const trimmed = name.trim();
    if (trimmed.length === 0) {
      throw new DomainValidationError("User name must not be empty");
    }
    return new User(id, trimmed);
  }
}

